command:
$ErrorActionPreference="Stop"
$probe=Join-Path $env:RUNNER_TEMP ("hc-settings-toggle2-"+$env:GITHUB_RUN_ID+".py")
@'
import ctypes as c
from ctypes import wintypes as w
import subprocess,time
from pywinauto import Desktop,keyboard
class HC(c.Structure):
    _fields_=(("cbSize",w.UINT),("dwFlags",w.DWORD),("lpszDefaultScheme",w.LPWSTR))
u=c.WinDLL("user32",use_last_error=True)
def hc():
    x=HC();x.cbSize=c.sizeof(x);assert u.SystemParametersInfoW(0x0042,x.cbSize,c.byref(x),0);return bool(x.dwFlags&1),x.lpszDefaultScheme
def until(fn,label,seconds=25):
    end=time.monotonic()+seconds
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:pass
        time.sleep(.25)
    raise AssertionError(label)
def close_settings():
    for x in Desktop(backend="uia").windows():
        if x.window_text() in ("설정","Settings"):
            try:x.close()
            except Exception:pass
    time.sleep(1)
def page():
    close_settings()
    subprocess.Popen(["cmd","/c","start","","ms-settings:easeofaccess-highcontrast"])
    def find():
        for win in reversed(Desktop(backend="uia").windows()):
            apply=win.child_window(auto_id="HighContrastThemeApplyButton")
            if apply.exists(timeout=.1):
                combos=[x for x in win.descendants(control_type="ComboBox") if x.is_visible()]
                if combos:return win,combos[0],apply.wrapper_object()
        return None
    return until(find,"Contrast themes page unavailable")
def set_target(on):
    before,_=hc();print("HC_SMOKE_BEFORE",on,before,flush=True)
    if before==on:return
    win,combo,apply=page()
    print("HC_SMOKE_PAGE",win.window_text(),repr(combo.window_text()),flush=True)
    try:
        combo.select("밤하늘" if on else "없음")
    except Exception as ex:
        print("HC_SMOKE_SELECT_FALLBACK",repr(ex),flush=True)
        combo.click_input();keyboard.send_keys("{END}{ENTER}" if on else "{HOME}{ENTER}")
    time.sleep(.5)
    print("HC_SMOKE_COMBO_AFTER",repr(combo.window_text()),flush=True)
    apply.click_input()
    until(lambda:hc()[0]==on,"Apply did not change High Contrast",30)
    after,scheme=hc();print("HC_SMOKE_AFTER",on,after,repr(scheme),flush=True)
    close_settings()
original,_=hc();failure=None
print("HC_SMOKE_ORIGINAL",original,flush=True)
try:
    set_target(True)
    set_target(False)
    print("HIGH_CONTRAST_SETTINGS_TOGGLE_SMOKE_PASS",flush=True)
except Exception as ex:
    failure=ex
finally:
    if hc()[0]!=original:
        try:set_target(original)
        except Exception as rex:print("HC_SMOKE_RESTORE_ERROR",repr(rex),flush=True)
    close_settings()
    print("HC_SMOKE_FINAL",hc()[0],flush=True)
if failure:raise failure

'@ | Set-Content -LiteralPath $probe -Encoding UTF8
& python -X utf8 $probe
$code=$LASTEXITCODE
Remove-Item $probe -Force -ErrorAction SilentlyContinue
if($code -ne 0){throw "Contrast themes clean-open toggle smoke failed"}
Write-Host "HIGH_CONTRAST_SETTINGS_CLEAN_OPEN_TOGGLE_PASS"
